async function readAll(id,pointer=""){
let q=JSON.parse(await tools.read_task_input({id,pointer}));
if(q.accepted===false)throw Error(q.error);
if(q.view==="string"){let s=q.value;while(q.has_more){q=JSON.parse(await tools.read_task_input({id,pointer,offset:q.next_offset}));s+=q.value;}return s;}
if(q.view==="value")return q.value;
let keys=[...q.keys];while(q.has_more){q=JSON.parse(await tools.read_task_input({id,pointer,offset:q.next_offset}));keys.push(...q.keys);}
const out=q.container==="array"?[]:{};
for (const k of keys)out[k]=await readAll(id,pointer+"/"+String(k).replace(/~/g,"~0").replace(/\//g,"~1"));
return out;
}
for(const id of ["nl0.json","contract.json","source-map.json","background-supplement.json","type-result.json"]){const v=await readAll(id);store(id,v);text({id,chars:JSON.stringify(v).length,keys:Object.keys(v)});}
text({typeResult:load("type-result.json")});

