const n=load("nl0.json"),c=load("contract.json"),p=load("plan.json"),sm=load("source-map.json");
const byId=Object.fromEntries(p.steps.map(s=>[s.id,s]));
function roots(id){const s=byId[id];return s?[...new Set(s.inputs.flatMap(roots))].sort():[id];}
text(p.steps.map((s,i)=>({i,id:s.id,statement:s.statement,inputs:s.inputs,roots:roots(s.id),paragraphs:s.source_steps})));
text({uncovered:sm.source_steps.filter(s=>!p.steps.some(t=>t.source_steps.includes(s.id))).map(s=>s.id),onlyOriginalPremises:c.premises.map(x=>x.id),outputMatch:n.propositions.filter(x=>["hypothesis","external"].includes(x.kind)).every(x=>c.premises.find(y=>y.id===x.id)?.statement===x.statement)});
text(load("background-supplement.json").notes.R009);
text(load("background-supplement.json").notes.R010);

